}

/* Inputs */
.raw-input-box {
  width: 100%;
  height: 44px;
  background: var(--bg-input);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-sm);
  color: var(--text-vivid);
  font-family: inherit;
  font-size: 0.9rem;
  padding: 0 0.85rem;
  outline: none;
  transition: all 0.15s ease;
}

.raw-input-box:focus {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.raw-textarea-box {
  width: 100%;
  min-height: 100px;
  background: var(--bg-input);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-sm);
  color: var(--text-vivid);
  font-family: "JetBrains Mono", monospace;
  font-size: 0.88rem;
  padding: 0.85rem;
  outline: none;
  resize: vertical;
  line-height: 1.6;
  transition: all 0.15s ease;
}

.raw-textarea-box:focus {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

/* Single Selector Styles */
.notion-combobox-wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  overflow: visible !important;
}

.notion-combobox-trigger {
  width: 100%;
  min-height: 44px;
  background: var(--bg-input);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  padding: 0.35rem 0.85rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.notion-combobox-trigger:hover,
.notion-combobox-trigger.active {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.selected-val-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid var(--accent-border);
  padding: 0.2rem 0.6rem;
  border-radius: 4px;
  font-weight: 600;
  font-size: 0.85rem;
}

.combobox-chevron {
  color: var(--text-muted);
  font-size: 0.8rem;
  transition: transform 0.2s ease;
}

.notion-combobox-trigger.active .combobox-chevron {
  transform: rotate(180deg);
  color: var(--accent);
}

/* Suggestor Monolith */
.suggestor-host {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  overflow: visible !important;
}

.searcher-monolith {
  width: 100%;
  height: 44px;
  background: var(--bg-input);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  padding: 0 0.85rem;
  gap: 0.65rem;
  transition: all 0.15s ease;
}

.searcher-monolith:focus-within {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.searcher-icon {
  color: var(--accent);
  font-size: 1rem;
  flex-shrink: 0;
  user-select: none;
}

.searcher-input {
  width: 100%;
  height: 100%;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text-vivid);
  font-size: 0.9rem;
  font-family: inherit;
}

.searcher-clear {
  background: rgba(255, 255, 255, 0.08);
  border: none;
  color: var(--text-muted);
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 0.75rem;
  flex-shrink: 0;
}

/* Selected Chips */
.selected-chips-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.selected-chips-row:empty { display: none; }

.chip-badge {
