function switchMainView(viewType, btn) {
  document.querySelectorAll('.view-container').forEach(v => v.classList.remove('active'));
  document.querySelectorAll('.nav-tab-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  if (viewType === 'quote-entry') {
    document.getElementById('quotes-view').classList.add('active');
  } else {
    document.getElementById('table-studio-view').classList.add('active');
  }
}

function openTableView(tableKey, btn) {
  currentTableKey = tableKey;
  switchMainView('table-studio', btn);

  const config = TABLES_CONFIG[tableKey];
  document.getElementById('studio-table-title').textContent = config.title;
  document.getElementById('studio-table-desc').textContent = config.desc;
  document.getElementById('studio-create-btn').textContent = `+ New ${tableKey.slice(0, -1)}`;
  document.getElementById('studio-table-search').value = "";

  renderActiveTable();
}

function renderActiveTable(filteredList = null) {
  const config = TABLES_CONFIG[currentTableKey];
  const data = filteredList || config.getData();

  // Render Headers
  const thead = document.getElementById('studio-table-thead');
  thead.innerHTML = `
    <tr>
      ${config.columns.map(col => `<th>${col.label}</th>`).join('')}
      <th style="text-align:right;">Actions</th>
    </tr>
  `;

  // Render Rows
  const tbody = document.getElementById('studio-table-tbody');
  if (data.length === 0) {
    tbody.innerHTML = `<tr><td colspan="${config.columns.length + 1}" style="text-align:center; color:var(--text-muted); padding:1.5rem;">No records found in table.</td></tr>`;
    return;
  }

  tbody.innerHTML = data.map(row => {
    const cells = config.columns.map(col => {
      let val = row[col.key];
      if (val === undefined || val === null) {
        if (col.key === 'idx') val = row.index;
        else if (col.key === 'index') val = row.idx;
      }
      let formatted = col.format ? col.format(val, row) : (val !== null && val !== undefined ? val : '—');
      let style = col.isMono ? "font-family:'JetBrains Mono'; font-size:0.75rem; color:var(--text-dim);" : (col.isBold ? "font-weight:700; color:var(--text-vivid);" : "");
      return `<td style="${style}">${formatted}</td>`;
    }).join('');

    return `
      <tr>
        ${cells}
        <td style="text-align:right; white-space:nowrap;">
          <button class="btn-action" style="padding:0.25rem 0.5rem; font-size:0.75rem;" onclick="openEditRecordModal('${row.id}')">✏️ Edit</button>
          <button class="btn-action btn-danger" style="padding:0.25rem 0.5rem; font-size:0.75rem;" onclick="deleteRecord('${row.id}')">🗑️</button>
        </td>
      </tr>
    `;
  }).join('');
}

function filterActiveTable(q) {
  const config = TABLES_CONFIG[currentTableKey];
  const data = config.getData();
  const query = (q || "").toLowerCase().trim();

  if (!query) {
    renderActiveTable(data);
    return;
  }

  const filtered = data.filter(row => {
    const directMatch = Object.values(row).some(val => {
      if (typeof val === 'string') return val.toLowerCase().includes(query);
      if (typeof val === 'number') return String(val).includes(query);
      if (Array.isArray(val)) return val.some(item => String(item).toLowerCase().includes(query));
      return false;
    });
    if (directMatch) return true;

    if (row.theme_ids && Array.isArray(row.theme_ids)) {
      if (row.theme_ids.some(tid => {
        const t = availableThemes.find(item => item.id === tid);
        return t && t.name.toLowerCase().includes(query);
      })) return true;
    }

    if (row.specific_id) {
      const s = availableSpecifics.find(item => item.id === row.specific_id);
      if (s && (s.name.toLowerCase().includes(query) || (s.container && s.container.name.toLowerCase().includes(query)))) return true;
    }

    return false;
  });
  renderActiveTable(filtered);
}

function openCreateRecordModal() {
  const config = TABLES_CONFIG[currentTableKey];
  document.getElementById('generic-modal-title').textContent = `+ Create New in ${config.title}`;
  renderGenericModalFields({}, false);
  openModal('generic-modal');
}

function openEditRecordModal(id) {
  const config = TABLES_CONFIG[currentTableKey];
  const data = config.getData();
  const record = data.find(r => r.id === id);
  if (!record) return;

  document.getElementById('generic-modal-title').textContent = `✏️ Edit Record in ${config.title}`;
  renderGenericModalFields(record, true);
  openModal('generic-modal');
}

